package com.bank.agent;

import java.lang.instrument.*;
import java.security.ProtectionDomain;
import java.util.logging.*;

// A Java Agent: loaded via -javaagent, runs premain BEFORE the app's main.
public class TimingAgent {
    private static final Logger log = Logger.getLogger(TimingAgent.class.getName());

    // Entry point for start-up attachment. Receives the Instrumentation control panel.
    public static void premain(String agentArgs, Instrumentation inst) {
        log.info(() -> "TimingAgent premain starting; args=" + agentArgs);
        inst.addTransformer(new TimingTransformer());   // register our bytecode rewriter
        // For dynamic attach to a RUNNING JVM, we'd add agentmain(...) with the same body
        // and (optionally) inst.retransformClasses(...) to instrument already-loaded classes.
    }
}

// ─── Would be in agent/.../TimingTransformer.java ───
class TimingTransformer implements ClassFileTransformer {
    private static final Logger log = Logger.getLogger(TimingTransformer.class.getName());

    // Called by the JVM for EVERY class as it loads, with the raw bytes.
    @Override
    public byte[] transform(ClassLoader loader, String className, Class<?> classBeingRedefined,
                            ProtectionDomain pd, byte[] classfileBuffer) {
        if (className == null || !className.equals("com/bank/app/service/TransferService")) {
            return null;   // null = leave class unchanged (don't touch what we don't care about)
        }
        log.info(() -> "Instrumenting " + className + " to add method timing");
        // In a real agent we'd rewrite classfileBuffer here with ByteBuddy/ASM to insert:
        //   long __start = System.nanoTime();   // at method entry
        //   try { ...original body... }
        //   finally { log time = System.nanoTime() - __start; }  // at every exit
        // ByteBuddy sketch (conceptual):
        //   return new ByteBuddy().redefine(classfileBuffer)
        //       .visit(Advice.to(TimingAdvice.class).on(named("transfer")))
        //       .make().getBytes();
        return classfileBuffer;  // (demo returns bytes unchanged; see TransferService note)
    }
}
