package com.bank.app.service;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

// Target service. NOT modified for timing — the agent adds that at load time.
public class TransferService {
    private static final Logger log = Logger.getLogger(TransferService.class.getName());
    private final Map<String, BigDecimal> balances = new HashMap<>();

    public TransferService() {
        balances.put("SAV2001", new BigDecimal("1000000.00"));  // Rajesh
        balances.put("CUR3001", new BigDecimal("250000.00"));   // Priya
    }

    // The agent weaves timing around THIS method (entry/exit) at load time.
    public void transfer(String fromId, String toId, BigDecimal amount) {
        BigDecimal from = balances.get(fromId);
        if (from.compareTo(amount) < 0) throw new IllegalStateException("Insufficient funds in " + fromId);
        balances.put(fromId, from.subtract(amount));
        balances.put(toId, balances.get(toId).add(amount));
        log.info(() -> "Transfer Rs." + amount + " from " + fromId + " to " + toId + " SUCCESS");
    }

    public BigDecimal balanceOf(String id) { return balances.get(id); }
}
