package com.bank.app;

import com.bank.app.service.TransferService;
import java.math.BigDecimal;
import java.util.logging.*;

public class TransferApp {
    private static final Logger log = Logger.getLogger(TransferApp.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // By the time main runs, premain has already registered the transformer,
        // so TransferService is instrumented as it loads here.
        var service = new TransferService();
        service.transfer("SAV2001", "CUR3001", new BigDecimal("50000.00"));
        log.info(() -> "Rajesh SAV2001 balance: Rs." + service.balanceOf("SAV2001"));
        log.info(() -> "Priya  CUR3001 balance: Rs." + service.balanceOf("CUR3001"));
        // With real ByteBuddy weaving, a line like this appears automatically:
        //   INFO: [TIMING] TransferService.transfer took 0.42 ms
    }
}
